class Solution {
public:
    int numDupDigitsAtMostN(int n) {
        string s = to_string(n);
        int k = s.size();

        auto perm = [](int m, int c) -> int {
            if (c > m || c < 0) return 0;
            int res = 1;
            for (int i = 0; i < c; ++i) res *= (m - i);
            return res;
        };

        int unique = 0;
        for (int len = 1; len < k; ++len) {
            unique += 9 * perm(9, len - 1);
        }

        vector<bool> seen(10, false);
        bool all_unique = true;
        for (int i = 0; i < k; ++i) {
            int d = s[i] - '0';
            int start = (i == 0) ? 1 : 0;
            for (int opt = start; opt < d; ++opt) {
                if (!seen[opt]) {
                    unique += perm(9 - i, k - 1 - i);
                }
            }
            if (seen[d]) {
                all_unique = false;
                break;
            }
            seen[d] = true;
        }
        if (all_unique) unique++;

        return n - unique;
    }
};

class Solution {
    public int numDupDigitsAtMostN(int n) {
        String s = String.valueOf(n);
        int k = s.length();

        int unique = 0;
        for (int len = 1; len < k; ++len) {
            unique += 9 * perm(9, len - 1);
        }

        boolean[] seen = new boolean[10];
        boolean allUnique = true;
        for (int i = 0; i < k; ++i) {
            int d = s.charAt(i) - '0';
            int start = (i == 0) ? 1 : 0;
            for (int opt = start; opt < d; ++opt) {
                if (!seen[opt]) {
                    unique += perm(9 - i, k - 1 - i);
                }
            }
            if (seen[d]) {
                allUnique = false;
                break;
            }
            seen[d] = true;
        }
        if (allUnique) unique++;

        return n - unique;
    }

    private int perm(int m, int c) {
        if (c > m || c < 0) return 0;
        int res = 1;
        for (int i = 0; i < c; ++i) res *= (m - i);
        return res;
    }
}

var numDupDigitsAtMostN = function(n) {
    const s = String(n);
    const k = s.length;

    const perm = (m, c) => {
        if (c > m || c < 0) return 0;
        let res = 1;
        for (let i = 0; i < c; i++) res *= (m - i);
        return res;
    };

    let unique = 0;
    for (let len = 1; len < k; len++) {
        unique += 9 * perm(9, len - 1);
    }

    const seen = new Set();
    let allUnique = true;
    for (let i = 0; i < k; i++) {
        const d = Number(s[i]);
        const start = (i === 0) ? 1 : 0;
        for (let opt = start; opt < d; opt++) {
            if (!seen.has(opt)) {
                unique += perm(9 - i, k - 1 - i);
            }
        }
        if (seen.has(d)) {
            allUnique = false;
            break;
        }
        seen.add(d);
    }
    if (allUnique) unique++;

    return n - unique;
};
